result:
 /deep/.ivu-input{
     font-size: 12px!important;
  }
.dragArea{
	padding-bottom: 20px;
}
.footer{
	padding: 0 15px;
}
.tips{
	font-size: 12px
	color: #BBBBBB
}
.box-item{
	position: relative
	display: flex
	margin-top: 15px
	padding: 20px 20px 20px 0
	background: #F9F9F9;
	border-radius: 3px;
	.del-box{
		position: absolute
		right: -13px
		top: -18px
		cursor: pointer
		.iconfont{
			color: #ccc
			font-size: 24px
		}
	}
}
    .left-tool{
		display: flex
		align-items: center
		justify-content: center
		width: 42px
		.iconfont{
			color: #999
			font-size: 18px
			cursor: move
		}
	}
    .right-wrapper{
		flex: 1
		.title {
			color: #999999;
			font-size: 12px;
			width: 50px;
			margin-top: 23px;
		}
		.img-wrapper{
			display: flex
			.img-item{
				width: 64px
				margin-right: 20px
				.name{
					color: #BBBBBB;
					font-size: 12px;
					text-align: center;
					margin-top: 7px;
				}
				.pictrue{
					width: 100%;
					height: 64px;
					cursor: pointer
					border: 1px solid #EEEEEE;
					position: relative
					border-radius: 3px;
				}
				img {
					display: block
					width: 100%
					height: 100%
				}
				.empty-img{
					display: flex
					align-items: center
					justify-content: center
					flex-direction: column
					width: 100%
					height: 100%
					font-size: 12px
					color: #BFBFBF
					border: 1px solid #EEEEEE;
					border-radius: 3px;
					.iconfont{
						font-size: 24px
					}
				}
				.txt{
					position: absolute
					left: 0
					bottom: 0
					width: 100%
					height: 22px
					line-height: 22px
					text-align: center
					background: rgba(0, 0, 0, 0.5);
					color: #fff
					font-size: 12px
					border-radius: 0 0 3px 3px;
				}
			}
		}
		.c_row-item{
			margin-top: 10px
			.label {
				color: #999999
				font-size: 12px
			}
		}
	}
.add-btn{
	width: 100%
	height: 40px
	margin-bottom: 30px;
}
